static void test_ntfs_checkpoint_and_journal_validation(void){cache_header h={.serial=42,.journal=77,.cursor=100};USN_JOURNAL_DATA j={.UsnJournalID=77,.FirstUsn=50,.LowestValidUsn=20,.NextUsn=200};CHECK("matching checkpoint admitted",checkpoint_ok(&h,42,&j));h.cursor=49;CHECK("trimmed checkpoint rejected",!checkpoint_ok(&h,42,&j));h.cursor=201;CHECK("future checkpoint rejected",!checkpoint_ok(&h,42,&j));h.cursor=100;CHECK("different disk rejected",!checkpoint_ok(&h,43,&j));j.UsnJournalID++;CHECK("new journal identity rejected",!checkpoint_ok(&h,42,&j));j.UsnJournalID--;j.LowestValidUsn=101;CHECK("lowest valid USN enforced",!checkpoint_ok(&h,42,&j));
 cached *c=calloc(1,sizeof *c);uint8_t bytes[88]={0};put64(bytes,180);bytes[8]=80;bytes[12]=2;put64(bytes+16,(UINT64_C(3)<<48)|7);put64(bytes+24,456);put64(bytes+32,100);bytes[64]=2;bytes[66]=60;bytes[68]='x';uint64_t next=0;CHECK("bounded v2 journal frame admitted",journal_chunk(c,bytes,sizeof bytes,100,200,&next)&&c->count==1&&next==180);CHECK("full sequence identity retained",c->queue[0].ref==((UINT64_C(3)<<48)|7));c->count=0;CHECK("fixed fence does not consume later records",journal_chunk(c,bytes,sizeof bytes,100,100,&next)&&!c->count);bytes[12]=3;CHECK("unknown record version fails closed",!journal_chunk(c,bytes,sizeof bytes,100,200,&next));bytes[12]=2;bytes[8]=79;CHECK("unaligned frame rejected",!journal_chunk(c,bytes,sizeof bytes,100,200,&next));bytes[8]=80;bytes[64]=100;CHECK("filename bounds rejected",!journal_chunk(c,bytes,sizeof bytes,100,200,&next));bytes[64]=2;put64(bytes,100);CHECK("non-progress cursor rejected",!journal_chunk(c,bytes,sizeof bytes,100,200,&next));put64(bytes,180);put64(bytes+32,99);CHECK("backwards record USN rejected",!journal_chunk(c,bytes,sizeof bytes,100,200,&next));CHECK("truncated prefix rejected",!journal_chunk(c,bytes,7,100,200,&next));free(c->queue);free(c);}
static int no_longer_alive(void *unused){(void)unused;return 0;}
