 WIN32_FIND_DATAW entry;wchar_t pattern[MAX_PATH+80];swprintf(pattern,MAX_PATH+80,L"%ls.pending-%lu-*",path,GetCurrentProcessId());HANDLE find=FindFirstFileW(pattern,&entry);CHECK("interrupted own candidate retained",find!=INVALID_HANDLE_VALUE);if(find!=INVALID_HANDLE_VALUE){wchar_t candidate[MAX_PATH+80];wchar_t *slash=wcsrchr(path,L'\\');size_t prefix=(size_t)(slash-path)+1;memcpy(candidate,path,prefix*2);wcscpy(candidate+prefix,entry.cFileName);CHECK("test removes only exact owned candidate",DeleteFileW(candidate));FindClose(find);}
