 cached quiet={.owner=INVALID_HANDLE_VALUE};CHECK("unchanged checkpoint skips cache IO",ntfs_cache_save(&quiet)==0&&!quiet.h.generation);quiet.save_needed=1;CHECK("dirty model cannot silently skip persistence",ntfs_cache_save(&quiet)!=0&&quiet.save_needed);quiet.save_needed=0;quiet.h.cursor=1;CHECK("advanced journal checkpoint still requires persistence",ntfs_cache_save(&quiet)!=0);
