 r.id=2;r.parent=3;r.flags=SP_DIR;CHECK("cycle rejected before mutation",!space_model_record(&m,&r,L"cycle"));m.error=0;r.id=3;r.type=SP_REMOVE;CHECK("removed entry detached",space_model_record(&m,&r,NULL));CHECK("removed allocation and paths disappear",m.nodes[0].sum.allocated==0&&!space_model_path(&m,3,L"C:\\"));uint32_t count;sp_row *rows=space_model_rows(&m,0,1,0,0,L"",NULL,NULL,&count);CHECK("removed file not searchable in views",count==0);free(rows);
