static uint64_t fixture_ref(uint32_t id,uint16_t sequence){return ((uint64_t)sequence<<48)|id;}
static int fixture_name(mft_model *m,uint64_t child,uint64_t parent,const wchar_t *name){uint32_t n=(uint32_t)wcslen(name);if(!reserve_names(m,1,n+1))return 0;uint32_t offset=m->text_count;memcpy(m->text+offset,name,(n+1)*2);m->text_count+=n+1;m->names[m->name_count++]=(mft_name){.child=child,.parent=parent,.offset=offset,.length=(uint16_t)n,.space=3,.next=MFT_NONE};return 1;}
static mft_model fixture_record(uint32_t id,uint16_t sequence,uint16_t flags,uint64_t size,uint64_t parent,const wchar_t *name){mft_model m={.slots=1,.cluster_size=4096};m.nodes=calloc(1,sizeof *m.nodes);if(!m.nodes)return m;m.nodes[0]=(mft_node){.reference=fixture_ref(id,sequence),.flags=flags,.first=MFT_NONE,.links=1,.logical=size,.allocated=size?4096:0,.all_logical=size,.all_allocated=size?4096:0,.streams=flags&MF_DATA?1:0};if(name&&!fixture_name(&m,m.nodes[0].reference,parent,name)){mft_free(&m);return (mft_model){0};}return m;}
static int fixture_apply(cached *c,uint32_t id,mft_model *record){int got=record&&record->nodes;int ok=ensure_slots(c,id)&&apply_record(c,id,got,got?record->nodes[0].reference:0,got?record:&(mft_model){0});return ok;}
static cached *fixture_cache(void){cached *c=calloc(1,sizeof *c);if(!c)return NULL;c->geometry.BytesPerCluster=4096;c->geometry.BytesPerFileRecordSegment=1024;c->h=(cache_header){.serial=42,.journal=77,.cursor=100};c->m.slots=64;c->m.cluster_size=4096;c->m.nodes=calloc(64,sizeof *c->m.nodes);if(!c->m.nodes){ntfs_cache_close(c);return NULL;}c->m.nodes[5]=(mft_node){.reference=fixture_ref(5,2),.flags=MF_ACTIVE|MF_DIRECTORY,.first=MFT_NONE};for(uint32_t id=6;id<10;id++){mft_model r=fixture_record(id,2,id<8?MF_ACTIVE|MF_DIRECTORY:MF_ACTIVE|MF_DATA,id<8?0:10,fixture_ref(id<8?5:6,2),id==6?L"left":id==7?L"right":id==8?L"one.txt":L"two.bin");if(!r.nodes||!fixture_name(&c->m,r.nodes[0].reference,r.names[0].parent,(wchar_t*)r.text)){mft_free(&r);ntfs_cache_close(c);return NULL;}c->m.nodes[id]=r.nodes[0];mft_free(&r);}if(!compact(c)){ntfs_cache_close(c);return NULL;}return c;}
/* Independent full-resolve oracle plus index coverage checks. Name order and
 * physical arena offsets may differ; live identities/metadata/aliases may not. */
static int matches_full_resolve(cached *c){mft_model o={.slots=c->m.slots,.cluster_size=c->m.cluster_size};o.nodes=malloc((size_t)o.slots*sizeof *o.nodes);o.names=malloc((size_t)(c->m.name_count?c->m.name_count:1)*sizeof *o.names);o.text=malloc((size_t)(c->m.text_count?c->m.text_count:1)*2);uint8_t *children=calloc(c->m.name_count?c->m.name_count:1,1),*parents=calloc(c->m.name_count?c->m.name_count:1,1);int ok=o.nodes&&o.names&&o.text&&children&&parents;if(!ok)goto done;memcpy(o.nodes,c->m.nodes,(size_t)o.slots*sizeof *o.nodes);memcpy(o.text,c->m.text,(size_t)c->m.text_count*2);o.text_count=c->m.text_count;for(uint32_t i=0;i<c->m.name_count;i++)if(c->m.names[i].child){o.names[o.name_count]=c->m.names[i];o.names[o.name_count].valid=0;o.names[o.name_count++].next=MFT_NONE;}mft_resolve(&o);ok=o.bad_sequence==c->m.bad_sequence;
 for(uint32_t id=0;ok&&id<o.slots;id++){if(!metadata_equal(o.nodes+id,c->m.nodes+id)){ok=0;break;}uint32_t a=0,b=0;for(uint32_t i=c->m.nodes[id].first;i!=MFT_NONE;i=c->m.names[i].next){if(i>=c->m.name_count||++a>c->m.name_count){ok=0;break;}mft_name *n=c->m.names+i;int found=0;for(uint32_t j=o.nodes[id].first;j!=MFT_NONE;j=o.names[j].next){mft_name *q=o.names+j;if(n->child==q->child&&n->parent==q->parent&&n->length==q->length&&!memcmp(c->m.text+n->offset,o.text+q->offset,n->length*2)){found=1;break;}}if(!n->valid||!found)ok=0;}for(uint32_t j=o.nodes[id].first;j!=MFT_NONE;j=o.names[j].next)b++;if(a!=b)ok=0;
  for(uint32_t i=c->all_heads[id],n=0;i!=MFT_NONE;i=c->edges[i].child_next){if(i>=c->m.name_count||++n>c->m.name_count||children[i]++||(c->m.names[i].child&MFT_INDEX_MASK)!=id){ok=0;break;}}
 }
 for(uint32_t p=0;ok&&p<c->parent_capacity;p++)if(c->parents[p].key){uint32_t previous=MFT_NONE;for(uint32_t i=c->parents[p].first,n=0;i!=MFT_NONE;i=c->edges[i].parent_next){if(i>=c->m.name_count||++n>c->m.name_count||parents[i]++||c->edges[i].parent_previous!=previous||(c->m.names[i].parent&MFT_INDEX_MASK)!=c->parents[p].key-1){ok=0;break;}previous=i;}}
 for(uint32_t i=0;ok&&i<c->m.name_count;i++)if(!!c->m.names[i].child!=(children[i]==1&&parents[i]==1))ok=0;
 done:free(children);free(parents);mft_free(&o);return ok;}
