 r=fixture_record(8,2,MF_ACTIVE|MF_DATA,1020,fixture_ref(7,2),L"renamed.txt");fixture_name(&r,r.nodes[0].reference,fixture_ref(7,2),L"renamed.txt");CHECK("duplicate namespace aliases collapse exactly as full resolver",fixture_apply(c,8,&r)&&finish_refresh(c)&&matches_full_resolve(c)&&c->m.nodes[8].first!=MFT_NONE&&c->m.names[c->m.nodes[8].first].next==MFT_NONE);mft_free(&r);ntfs_cache_ack_changes(c);
