 channel c={.pipe=INVALID_HANDLE_VALUE};sp_record root={.magic=SP_MAGIC,.type=SP_ENTRY,.flags=SP_DIR,.parent=SP_NONE},failure={.magic=SP_MAGIC,.type=NTN_ERROR,.error=ERROR_ACCESS_DENIED};memcpy(c.data,&root,sizeof root);memcpy(c.data+sizeof root,&failure,sizeof failure);c.used=sizeof root+sizeof failure;delivery_result result={0};DWORD error=stream_records(&c,delivery_collect,&result);CHECK("worker failure retains earlier valid records and exact error",error==ERROR_ACCESS_DENIED&&result.records==1);space_model_free(&result.model);
