static int checkpoint_files_equal(const wchar_t *a,const wchar_t *b){FILE *fa=_wfopen(a,L"rb"),*fb=_wfopen(b,L"rb");int ok=fa&&fb;if(ok){uint8_t x[4096],y[4096];for(;;){size_t nx=fread(x,1,sizeof x,fa),ny=fread(y,1,sizeof y,fb);if(nx!=ny||memcmp(x,y,nx)){ok=0;break;}if(nx<sizeof x){ok=!ferror(fa)&&!ferror(fb);break;}}}if(fa)fclose(fa);if(fb)fclose(fb);return ok;}
static int checkpoint_change(cached *c,uint32_t id,uint16_t sequence,uint16_t flags,uint64_t size,uint32_t parent,const wchar_t *name){mft_model r=fixture_record(id,sequence,flags,size,fixture_ref(parent,2),name);int ok=r.nodes&&fixture_apply(c,id,&r)&&finish_refresh(c);mft_free(&r);ntfs_cache_ack_changes(c);return ok;}
static int checkpoint_remove_owned_pending(const wchar_t *path){wchar_t pattern[MAX_PATH+80];swprintf(pattern,MAX_PATH+80,L"%ls.pending-%lu-*",path,GetCurrentProcessId());WIN32_FIND_DATAW item;HANDLE search=FindFirstFileW(pattern,&item);if(search==INVALID_HANDLE_VALUE)return GetLastError()==ERROR_FILE_NOT_FOUND;int ok=1;const wchar_t *slash=wcsrchr(path,L'\\');size_t prefix=slash?(size_t)(slash-path)+1:0;do{wchar_t candidate[MAX_PATH+80];memcpy(candidate,path,prefix*2);wcscpy(candidate+prefix,item.cFileName);if(item.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY||!DeleteFileW(candidate))ok=0;}while(FindNextFileW(search,&item));FindClose(search);return ok;}
